//! Golden vectors generated by the Go bridge and ledger.
//!
//! `testdata/events/*.json` maps a wire `DueEvent` to the script, variables and
//! ack outcome the executor must produce. `testdata/ledger/v1.json` pins the
//! on-disk JSON, retention and receipt cap.

use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use home_ha::Error;
use home_proto::v1::DueEvent;
use home_worker::{Event, Handler, Outcome};
use serde::Deserialize;
use serde_json::{Map, Value};
use tempfile::tempdir;

use ha_bridge::bridge::{Bridge, HaClient};
use ha_bridge::config::Config;
use ha_bridge::ledger::{ActiveAlarm, Ledger, Receipt};

fn testdata_dir() -> PathBuf {
    let relative = Path::new("solutions/ha-bridge/testdata");
    if std::env::var_os("TEST_SRCDIR").is_none() {
        return Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testdata");
    }
    for root in ["TEST_SRCDIR", "RUNFILES_DIR", "GULP_SRCDIR"] {
        let Ok(root) = std::env::var(root) else {
            continue;
        };
        let workspace = std::env::var("TEST_WORKSPACE").unwrap_or_default();
        let candidate = Path::new(&root).join(&workspace).join(relative);
        if candidate.is_dir() {
            return candidate;
        }
        let candidate = Path::new(&root).join(relative);
        if candidate.is_dir() {
            return candidate;
        }
    }
    relative.to_owned()
}

fn read_json(path: &Path) -> Value {
    let bytes =
        std::fs::read(path).unwrap_or_else(|error| panic!("read {}: {error}", path.display()));
    serde_json::from_slice(&bytes)
        .unwrap_or_else(|error| panic!("parse {}: {error}", path.display()))
}

#[derive(Debug, Deserialize)]
struct EventVector {
    name: String,
    event: Value,
    #[serde(rename = "activeAlarm", default)]
    active_alarm: Option<ActiveAlarm>,
    #[serde(default)]
    seen: bool,
    #[serde(rename = "haError", default)]
    ha_error: String,
    expected: Expected,
}

#[derive(Debug, Deserialize)]
struct Expected {
    outcome: String,
    #[serde(default)]
    detail: String,
    #[serde(default)]
    script: Option<String>,
    #[serde(default)]
    variables: Option<Map<String, Value>>,
}

struct FakeHa {
    calls: Mutex<Vec<(String, Map<String, Value>)>>,
    status: Option<u16>,
}

impl FakeHa {
    fn new(status: Option<u16>) -> Self {
        Self {
            calls: Mutex::new(Vec::new()),
            status,
        }
    }
}

impl HaClient for FakeHa {
    async fn call_script(&self, script: &str, variables: Map<String, Value>) -> Result<(), Error> {
        self.calls
            .lock()
            .expect("lock")
            .push((script.to_owned(), variables));
        self.status.map_or(Ok(()), |status| {
            Err(Error::Status {
                op: "call script",
                status,
                message: String::new(),
            })
        })
    }

    async fn ping(&self) -> Result<(), Error> {
        Ok(())
    }
}

fn config() -> Config {
    Config::load_from(
        &|key| match key {
            "HA_URL" => Some("http://ha.example:8123".to_owned()),
            "SCHEDULER_ENDPOINT" => Some("http://scheduler.example:8098".to_owned()),
            "SCHEDULER_TOKEN" => Some("scheduler-secret".to_owned()),
            "HA_TOKEN" => Some("ha-secret".to_owned()),
            "BRIDGE_CONSUMER_ID" => Some("ha-bridge-home".to_owned()),
            "BRIDGE_EXECUTE" => Some("true".to_owned()),
            _ => None,
        },
        &|_| Ok(Vec::new()),
    )
    .expect("config")
}

fn ha_status(name: &str) -> Option<u16> {
    if name.is_empty() {
        return None;
    }
    let (_, status) = name
        .rsplit_once('-')
        .unwrap_or_else(|| panic!("unknown haError {name}"));
    Some(
        status
            .parse::<u16>()
            .unwrap_or_else(|_| panic!("unknown haError {name}")),
    )
}

#[tokio::test]
async fn event_vectors_match_the_go_bridge() {
    let dir = testdata_dir().join("events");
    let mut files: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap_or_else(|error| panic!("read {}: {error}", dir.display()))
        .filter_map(|entry| entry.ok().map(|entry| entry.path()))
        .filter(|path| {
            path.extension()
                .is_some_and(|extension| extension == "json")
        })
        .collect();
    files.sort();
    assert!(!files.is_empty(), "no event vectors in {}", dir.display());

    for file in &files {
        let vectors = read_json(file);
        let vectors = vectors
            .as_array()
            .unwrap_or_else(|| panic!("{} is not an array", file.display()));
        for vector in vectors {
            let vector: EventVector = serde_json::from_value(vector.clone())
                .unwrap_or_else(|error| panic!("{}: {error}", file.display()));
            let due: DueEvent = serde_json::from_value(vector.event)
                .unwrap_or_else(|error| panic!("{}: decode event: {error}", file.display()));
            let event = Event::from(due);

            let ledger = Ledger::memory_with_clock(|| 1_700_000_000);
            if vector.seen && !event.id.is_empty() {
                ledger
                    .record(Receipt {
                        event_id: event.id.clone(),
                        source_id: event.source_id.clone(),
                        action: String::new(),
                        script: String::new(),
                        completed_unix: 1_700_000_000,
                    })
                    .expect("seed seen receipt");
            }
            if let Some(active) = &vector.active_alarm {
                ledger
                    .record_start(
                        Receipt {
                            event_id: active.event_id.clone(),
                            source_id: active.source_id.clone(),
                            action: "FIRE".to_owned(),
                            script: "alarm_start".to_owned(),
                            completed_unix: active.since_unix,
                        },
                        active.clone(),
                    )
                    .expect("seed active alarm");
            }

            let ha = Arc::new(FakeHa::new(ha_status(&vector.ha_error)));
            let bridge = Bridge::new(Arc::new(config()), Arc::clone(&ha), Arc::new(ledger));
            let outcome = bridge.handle(&event).await;

            match vector.expected.outcome.as_str() {
                "RETRY" => assert_eq!(outcome, Outcome::Retry, "{}", vector.name),
                "ACK_OUTCOME_DELIVERED" => assert_eq!(
                    outcome,
                    Outcome::Delivered(vector.expected.detail.clone()),
                    "{}",
                    vector.name
                ),
                "ACK_OUTCOME_FAILED" => assert_eq!(
                    outcome,
                    Outcome::Failed(vector.expected.detail.clone()),
                    "{}",
                    vector.name
                ),
                "ACK_OUTCOME_SKIPPED" => assert_eq!(
                    outcome,
                    Outcome::Skipped(vector.expected.detail.clone()),
                    "{}",
                    vector.name
                ),
                other => panic!("{}: unknown expected outcome {other}", vector.name),
            }

            let calls = ha.calls.lock().expect("lock");
            match &vector.expected.script {
                Some(script) => {
                    assert_eq!(calls.len(), 1, "{}: expected one HA call", vector.name);
                    assert_eq!(&calls[0].0, script, "{}: script", vector.name);
                    assert_eq!(
                        Some(&calls[0].1),
                        vector.expected.variables.as_ref(),
                        "{}: variables",
                        vector.name
                    );
                }
                None => assert!(calls.is_empty(), "{}: unexpected HA call", vector.name),
            }
        }
    }
}

#[derive(Debug, Deserialize)]
struct LedgerFixture {
    #[serde(rename = "clockUnix")]
    clock_unix: i64,
    canonical: String,
    replay: Vec<Receipt>,
    #[serde(rename = "activeAlarm", default)]
    active_alarm: Option<ActiveAlarm>,
    prune: PruneFixture,
    trim: TrimFixture,
    invalid: Vec<InvalidFixture>,
}

#[derive(Debug, Deserialize)]
struct PruneFixture {
    #[serde(rename = "retentionSeconds")]
    retention_seconds: i64,
    receipts: Vec<Receipt>,
    #[serde(rename = "expectedKept")]
    expected_kept: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct TrimFixture {
    #[serde(rename = "maxReceipts")]
    max_receipts: usize,
    count: usize,
    #[serde(rename = "firstCompletedUnix")]
    first_completed_unix: i64,
    #[serde(rename = "expectedKept")]
    expected_kept: usize,
    #[serde(rename = "expectedRemoved")]
    expected_removed: usize,
}

#[derive(Debug, Deserialize)]
struct InvalidFixture {
    name: String,
    body: String,
    error: String,
}

#[test]
fn ledger_vectors_match_the_go_ledger() {
    let fixture: LedgerFixture =
        serde_json::from_value(read_json(&testdata_dir().join("ledger/v1.json")))
            .expect("ledger fixture");
    let clock = fixture.clock_unix;

    // Round-trip: opening the canonical bytes and replaying the same writes
    // must leave the file byte-identical.
    let directory = tempdir().expect("tempdir");
    let path = directory.path().join("ledger.json");
    std::fs::write(&path, &fixture.canonical).expect("write canonical");
    let ledger = Ledger::open_with_clock(&path, move || clock).expect("open canonical");
    for receipt in &fixture.replay {
        if fixture
            .active_alarm
            .as_ref()
            .is_some_and(|active| active.event_id == receipt.event_id)
        {
            let active = fixture.active_alarm.clone().expect("active");
            ledger
                .record_start(receipt.clone(), active)
                .expect("record start");
        } else {
            ledger.record(receipt.clone()).expect("record");
        }
    }
    assert_eq!(
        std::fs::read_to_string(&path).expect("read"),
        fixture.canonical,
        "canonical ledger bytes changed"
    );
    assert_eq!(
        ledger.active_alarm(),
        fixture.active_alarm,
        "active alarm round-trip"
    );

    // Prune drops exactly the receipts older than the retention window.
    let retention = Duration::from_secs(u64::try_from(fixture.prune.retention_seconds).unwrap());
    assert_eq!(retention, ha_bridge::ledger::DEFAULT_RETENTION);
    assert_eq!(fixture.trim.max_receipts, ha_bridge::ledger::MAX_RECEIPTS);
    let prune_path = directory.path().join("prune.json");
    let prune_file = serde_json::json!({
        "version": 1,
        "receipts": fixture
            .prune
            .receipts
            .iter()
            .map(|receipt| (receipt.event_id.clone(), receipt))
            .collect::<std::collections::BTreeMap<_, _>>(),
    });
    std::fs::write(
        &prune_path,
        serde_json::to_vec(&prune_file).expect("encode"),
    )
    .expect("write prune");
    let pruned = Ledger::open_with_clock(&prune_path, move || clock).expect("open prune");
    let mut kept: Vec<String> = fixture
        .prune
        .receipts
        .iter()
        .filter(|receipt| pruned.seen(&receipt.event_id))
        .map(|receipt| receipt.event_id.clone())
        .collect();
    kept.sort();
    assert_eq!(kept, fixture.prune.expected_kept);

    // The cap keeps the newest receipts and never exceeds 20 000.
    let trim_path = directory.path().join("trim.json");
    let mut receipts = std::collections::BTreeMap::new();
    for index in 0..fixture.trim.count {
        let id = format!("evt-{index}");
        let completed = fixture.trim.first_completed_unix + i64::try_from(index).unwrap();
        receipts.insert(
            id.clone(),
            Receipt {
                event_id: id,
                source_id: String::new(),
                action: String::new(),
                script: String::new(),
                completed_unix: completed,
            },
        );
    }
    std::fs::write(
        &trim_path,
        serde_json::to_vec(&serde_json::json!({"version": 1, "receipts": receipts}))
            .expect("encode"),
    )
    .expect("write trim");
    let trimmed = Ledger::open_with_clock(&trim_path, move || clock).expect("open trim");
    // Re-recording an existing id triggers the same trim path as a new record
    // without changing the receipt set.
    trimmed
        .record(Receipt {
            event_id: "evt-0".to_owned(),
            source_id: String::new(),
            action: String::new(),
            script: String::new(),
            completed_unix: fixture.trim.first_completed_unix,
        })
        .expect("trigger trim");
    assert_eq!(trimmed.len(), fixture.trim.expected_kept);
    assert_eq!(
        fixture.trim.count - trimmed.len(),
        fixture.trim.expected_removed
    );
    assert!(!trimmed.seen("evt-0"), "the oldest receipt is dropped");
    assert!(
        !trimmed.seen(&format!("evt-{}", fixture.trim.expected_removed - 1)),
        "the last trimmed receipt is dropped"
    );
    assert!(
        trimmed.seen(&format!("evt-{}", fixture.trim.expected_removed)),
        "the first kept receipt survives"
    );
    assert!(
        trimmed.seen(&format!("evt-{}", fixture.trim.count - 1)),
        "the newest receipt is kept"
    );

    for invalid in &fixture.invalid {
        let path = directory
            .path()
            .join(format!("invalid-{}.json", invalid.name));
        std::fs::write(&path, &invalid.body).expect("write invalid");
        let error =
            Ledger::open_with_clock(&path, move || clock).expect_err("invalid ledger must fail");
        assert!(
            error.to_string().contains(&invalid.error),
            "{}: {error}",
            invalid.name
        );
    }
}
